INSERT INTO `weight_exercises` VALUES (1,'Bench Press','ท่าฝึกพื้นฐานระดับสากลที่ใช้บาร์เบลเพื่อสร้างมวลกล้ามเนื้ออกรวม ไหล่หน้า และแขนท่อนหลังให้หนาและทรงพลัง','นอนหงายบนม้านั่งราบ ตาตรงกับบาร์เบล จับบาร์กว้างกว่าหัวไหล่เล็กน้อย ปักสะบักติดม้านั่ง วางเท้าติดพื้นให้มั่นคง\nยกบาร์ออกจากแท่น ผ่อนบาร์ลงช้าๆ มาที่บริเวณราวนมล่าง (หายใจเข้า) จากนั้นออกแรงดันบาร์ขึ้นตรงๆ จนแขนตึงแต่ไม่ล็อกข้อศอก (หายใจออก)\nห้ามยกสะโพกลอยขึ้นจากม้านั่ง และห้ามปล่อยให้บาร์ตกกระแทกอก',2,1,'uploads/weight_exercises/image/BenchPress.jpg','https://youtube.com/shorts/SCVCLChPQFY',1,'uploads/weight_exercises/videoloop/BenchPress_loop.mp4',1),(2,'Incline Bench Press','ท่าดันบาร์เบลบนม้านั่งเอียงขึ้น เจาะจงเพื่อสร้างความหนาและความคมชัดให้กับกล้ามเนื้ออกส่วนบน','ปรับม้านั่งเอียงขึ้น 30-45 องศา นอนราบปักสะบักแน่น จับบาร์กว้างกว่าไหล่เล็กน้อย วางเท้าสองข้างติดพื้น\r\nปลดบาร์ลงช้าๆ มาที่บริเวณอกส่วนบน (ใต้กระดูกไหปลาร้าเล็กน้อย) แล้วออกแรงดันบาร์ขึ้นในแนวดิ่งจนสุดแขน\r\nอย่าปรับม้านั่งชันเกินไปเพราะแรงจะย้ายไปที่หัวไหล่หน้าแทนอกบน',2,1,'uploads/weight_exercises/image/InclineBenchPress.jpg','https://youtube.com/shorts/8fXfwG4ftaQ',1,'uploads/weight_exercises/videoloop/InclineBenchPress_loop.mp4',1),(3,'Decline Bench Press','ท่าดันบาร์เบลบนม้านั่งเอียงลง เน้นการตัดขอบและสร้างมิติกล้ามเนื้ออกส่วนล่างให้ชัดเจน','นอนบนม้านั่งเอียงลง ล็อกข้อเท้ากับเบาะให้แน่น ปักสะบักติดเบาะ จับบาร์กว้างกว่าไหล่เล็กน้อย\nปลดบาร์ลงช้าๆ มาที่บริเวณฐานอกล่าง (ใต้ราวนม) ออกแรงดันบาร์ขึ้นตรงๆ เกร็งอกส่วนล่าง\nระวังบาร์ไหลเข้าใกล้คอ ควรมียกเซฟหรือตั้งแร็กให้พอดี',2,1,'uploads/weight_exercises/image/DeclineBenchPress.jpg','',1,'uploads/weight_exercises/videoloop/DeclineBenchPress_loop.mp4',1),(4,'Dumbbell Flyes','ท่ากางแขนด้วยดัมเบลเพื่อเหยียดเค้นและกระตุ้นกล้ามเนื้ออกส่วนกลางให้ขยายกว้างขวางและหนาขึ้น','นอนหงายบนม้านั่งราบ ถือดัมเบลขึ้นตรงเหนืออก หันฝ่ามือเข้าหากัน งอข้อศอกเล็กน้อยเป็นมุมคงที่\r\nกางแขนออกด้านข้างช้าๆ จนรู้สึกยืดที่กล้ามเนื้ออก จากนั้นใช้แรงอกบีบดัมเบลกลับมาเจอกันที่จุดเริ่มต้น\r\nห้ามเหยียดแขนตึงเป๊ะตอนกาง และอย่าหย่อนดัมเบลลึกเกินไปจนเจ็บไหล่',2,2,'uploads/weight_exercises/image/DumbbellFlyes.jpg','https://youtube.com/shorts/rk8YayRoTRQ',1,'uploads/weight_exercises/videoloop/DumbbellFlyes_loop.mp4',1),(5,'Cable Crossover','ท่าดึงสายเคเบิลเพื่อแยกโฟกัสกล้ามเนื้ออกรวม และเน้นบีบสร้างมิติร่องอกตรงกลางให้ลึกและชัดเจน','ตั้งสายเคเบิลไว้ตำแหน่งสูง ยืนตรงกลาง ก้าวขามาข้างหน้าหนึ่งก้าวเพื่อความมั่นคง จับด้ามจับโน้มตัวไปข้างหน้าเล็กน้อย\r\nออกแรงกวาดมือทั้งสองข้างลงมาตัดกันที่ด้านหน้าบริเวณใต้เอวหรือหน้าสะโพก บีบอกให้แน่น แล้วผ่อนกลับช้าๆ\r\nอย่าใช้แรงเหวี่ยงจากลำตัว และรักษาจังหวะการผ่อนกลับไม่ให้ไหล่กระชาก',2,4,'uploads/weight_exercises/image/CableCrossover.jpg','https://youtube.com/shorts/y4RJDSOBEl8',1,'uploads/weight_exercises/videoloop/CableCrossover_loop.mp4',2),(6,'Chest Press Machine UPDATED (QA Edited)','ท่าดันอกด้วยเครื่องพินโหลด ช่วยล็อกมุมการเคลื่อนไหวให้ปลอดภัยและโฟกัสกล้ามเนื้ออกได้แม่นยำไม่กระจาย','ปรับเบาะนั่งให้ด้ามจับอยู่ระดับราวนม นั่งพิงเบาะให้สนิท ปักสะบัก วางเท้าสองข้างราบกับพื้น\nออกแรงดันด้ามจับไปข้างหน้าจนสุดแขน (ไม่ล็อกข้อศอก) เกร็งอกขยับช้าๆ ตอนผ่อนน้ำหนักกลับ\nห้ามปล่อยให้แผ่นน้ำหนักกระแทกกัน และรักษาแนวศอกไม่ให้กางสูงเกินไป',1,3,'uploads/weight_exercises/image/ChestPressMachine.jpg','',1,'uploads/weight_exercises/videoloop/ChestPressMachine_loop.mp4',1),(7,'Deadlift','ราชาแห่งท่าฝึกพละกำลังที่เน้นสร้างความแข็งแรงและความหนาให้กับกล้ามเนื้อหลังรวมรวมถึงต้นขาด้านหลังทั้งหมด','ยืนเท้ากว้างเท่าช่วงสะโพก บาร์เบลอยู่กึ่งกลางหลังเท้า ก้มลงจับบาร์ (คว่ำมือหรือสลับมือ) หลังตรง หน้าอกเชิด ก้นงอน\r\nออกแรงถีบพื้นด้วยขาพร้อมดันสะโพกไปข้างหน้า ดึงบาร์เบลขึ้นมาจนยืนตรง เกร็งหลังและก้น ย้อนจังหวะเดิมตอนลง\r\nห้ามหลังค่อมเด็ดขาดขณะยกน้ำหนัก เพราะจะทำให้บาดเจ็บหลังส่วนล่างรุนแรง',3,1,'uploads/weight_exercises/image/Deadlift.jpg','https://youtube.com/shorts/xNwpvDuZJ3k',2,'uploads/weight_exercises/videoloop/Deadlift_loop.mp4',1),(8,'Pull-up','ท่าโหนบาร์ดึงตัวขึ้นด้วยน้ำหนักตัว เน้นสร้างแผ่นหลังส่วนปีกให้กว้างขวางเพื่อรูปทรงตัววี (V-Shape) ที่สวยงาม','กระโดดจับบาร์เดี่ยวแบบคว่ำมือ ความกว้างกว่าหัวไหล่เล็กน้อย ปล่อยตัวเหยียดตรง เกร็งแกนกลางลำตัว\nออกแรงดึงสะบักลง (Scapular Depression) แล้วดึงตัวขึ้นให้หน้าอกเข้าใกล้บาร์มากที่สุด จากนั้นผ่อนตัวลงช้าๆ\nห้ามเหวี่ยงขาหรือสะบัดตัวช่วยยก และระวังการทิ้งตัวลงมาเร็วเกินไป',3,5,'uploads/weight_exercises/image/Pullup.jpg','https://youtube.com/shorts/ym1V5H35IpA',2,'uploads/weight_exercises/videoloop/Pullup_loop.mp4',1),(9,'Lat Pulldown','ท่าดึงสายเคเบิลจากด้านบนลงมาเพื่อโฟกัสกล้ามเนื้อหลังส่วนปีก (Lats) ให้แผ่กว้างและหนาขึ้น','นั่งบนเครื่องปรับเบาะล็อกขาให้แน่น จับบาร์กว้างกว่าไหล่ เอนตัวไปข้างหลังเล็กน้อย เชิดอกขึ้น\r\nออกแรงดึงบาร์ลงมาหาอกส่วนบน บีบสะบักเข้าหากันเกร็งปีกหลัง แล้วค่อยๆ ผ่อนบาร์กลับขึ้นไปจนสุดแขน\r\nห้ามใช้แรงเหวี่ยงกระชากตัว และห้ามดึงบาร์ลงมาต่ำเกินไปจนศอกไปทางด้านหลัง',2,4,'uploads/weight_exercises/image/LatPulldown.jpg','uploads/weight_exercises/video/LatPulldown.mp4',2,'uploads/weight_exercises/videoloop/LatPulldown_loop.mp4',1),(10,'Barbell Row','ท่าก้มตัวดึงบาร์เบลเข้าหาลำตัว เน้นสร้างความหนาแน่นและรายละเอียดของกลุ่มกล้ามเนื้อหลังส่วนกลางและส่วนบน','ยืนแยกเท้าเท่าไหล่ ก้มพับสะโพกลงมาประมาณ 45 องศา หลังตรง จับบาร์เบลแบบคว่ำมือ ปล่อยแขนตึงในแนวดิ่ง\r\nออกแรงดึงบาร์เบลเข้าหาหน้าท้องส่วนล่าง บีบสะบักและศอกเข้าหาตัว เกร็งหลัง แล้วผ่อนบาร์ลงช้าๆ\r\nห้ามเด้งลำตัวขึ้นลงตามจังหวะยก และรักษาแนวหลังให้ตรงตลอดเวลา',2,1,'uploads/weight_exercises/image/BarbellRow.jpg','uploads/weight_exercises/video/BarbellRow.mp4',2,'uploads/weight_exercises/videoloop/BarbellRow_loop.mp4',1),(11,'One Arm Dumbbell Row','ท่าก้มตัวดึงดัมเบลทีละข้าง ช่วยยืดและบีบกล้ามเนื้อปีกหลังได้ลึก และช่วยลดปัญหาแรงซ้ายขวาไม่เท่ากัน','วางเข่าและมือข้างหนึ่งบนม้านั่งราบ ลำตัวขนานกับพื้น มืออีกข้างถือดัมเบลปล่อยแขนตึง หลังตรง\r\nออกแรงดึงดัมเบลขึ้นมาข้างลำตัว โดยโฟกัสที่การดึงข้อศอกไปทางด้านหลังจนสุดขอบ แล้วผ่อนลงช้าๆ\r\nห้ามบิดหมุนลำตัวหรือเอวขณะดึง และอย่าให้ไหล่ห่อตอนปล่อยน้ำหนักลง',2,2,'uploads/weight_exercises/image/OneArmDumbbellRow.jpg',NULL,2,'uploads/weight_exercises/videoloop/OneArmDumbbellRow_loop.mp4',1),(12,'Seated Cable Row','ท่านั่งดึงสายเคเบิลเข้าหาหน้าท้อง เพื่อเน้นสร้างความหนาเนื้อของกล้ามเนื้อหลังส่วนกลางและสะบัก','นั่งบนเครื่อง วางเท้าบนที่พัก เข่างอเล็กน้อย จับด้ามจับยืดหลังตรง เชิดอก ห้ามงอตัวไปข้างหน้า\r\nออกแรงดึงด้ามจับเข้าหาหน้าท้อง บีบสะบักสองข้างเข้าหากันให้แน่น ค้างไว้ 1 วินาที แล้วผ่อนกลับช้าๆ\r\nห้ามโยกเอนลำตัวไปข้างหน้าและข้างหลังมากเกินไป ให้แกนกลางอยู่นิ่งที่สุด',1,4,'uploads/weight_exercises/image/SeatedCableRow.jpg',NULL,2,'uploads/weight_exercises/videoloop/SeatedCableRow_loop.mp4',1),(13,'Face Pull','ท่าดึงเคเบิลเข้าหาระดับใบหน้า เพื่อบริหารกล้ามเนื้อไหล่หลังและหลังบน ช่วยปรับบุคลิกภาพและแก้ปัญหาไหล่ห่อ','ตั้งเคเบิลระดับใบหน้า ใช้เชือกจับ (Rope) ถอยหลังออกมาระดับหนึ่ง ยืนให้มั่นคง ยืดแขนตรงพุ่งหาเคเบิล\r\nออกแรงดึงเชือกเข้าหาใบหน้า พร้อมกางข้อศอกออกและแยกมือสองข้างออกจากกัน (จบในท่าเบ่งกล้าม Double Biceps)\r\nอย่าใช้น้ำหนักที่หนักเกินไปจนตัวเอนพุ่งไปข้างหน้า และระวังศอกตกขณะดึง',1,4,'uploads/weight_exercises/image/FacePull.jpg',NULL,2,'uploads/weight_exercises/videoloop/FacePull_loop.mp4',1),(14,'Overhead Press (OHP)','ท่าดันบาร์เบลขึ้นเหนือศีรษะในท่ายืน เพื่อสร้างความแข็งแรงและมวลกล้ามเนื้อหัวไหล่รวมถึงแกนกลางลำตัว','ยืนเท้ากว้างเท่าไหล่ จับบาร์เบลพาดไว้บนอกบน/ไหล่หน้า กำบาร์ให้ข้อมือตั้งตรง เกร็งท้องและก้นให้แน่น\r\nออกแรงดันบาร์เบลขึ้นตรงๆ เหนือศีรษะจนสุดแขน (เงยหน้าหลบบาร์เล็กน้อยขณะเคลื่อนที่) แล้วผ่อนลงมาที่จุดเริ่ม\r\nห้ามแอ่นหลังส่วนล่างเพื่อช่วยดันน้ำหนักเด็ดขาด เพราะเสี่ยงต่อการบาดเจ็บกระดูกสันหลัง',3,1,'uploads/weight_exercises/image/OverheadPress.jpg','https://youtube.com/shorts/zoN5EH50Dro',3,'uploads/weight_exercises/videoloop/OverheadPress_loop.mp4',1),(15,'Arnold Press','ท่าดันดัมเบลขึ้นเหนือศีรษะพร้อมหมุนข้อมือ เน้นบริหารและตัดเส้นหัวไหล่ให้ครบทั้งสามมิติ (หน้า ข้าง หลัง)','นั่งบนม้านั่งหลังตรง ถือดัมเบลไว้ด้านหน้าหันฝ่ามือเข้าหาตัวเอง (ท่าจบของ Bicep Curl) ระดับอก\r\nดันดัมเบลขึ้นเหนือศีรษะ พร้อมกับหมุนข้อมือออกด้านนอก ให้ฝ่ามือหันออกไปข้างหน้าตอนแขนเหยียดตึง\r\nควบคุมจังหวะการหมุนข้อมือให้สัมพันธ์กับการดันขึ้น อย่าหมุนเร็วกระชากเกินไป',2,2,'uploads/weight_exercises/image/ArnoldPress.jpg',NULL,3,'uploads/weight_exercises/videoloop/ArnoldPress_loop.mp4',1),(16,'Lateral Raise','ท่ากางแขนยกดัมเบลออกด้านข้าง เพื่อเจาะจงสร้างหัวไหล่ด้านข้างให้ขยายกว้างและดูกลมมนสวยงาม','ยืนตรงถือดัมเบลไว้ข้างลำตัว โน้มตัวไปข้างหน้าเล็กน้อย งอข้อศอกเล็กน้อยคงที่\r\nออกแรงกางแขนยกดัมเบลขึ้นด้านข้างจนแนวแขนขนานกับพื้น (ระดับไหล่) ค่อยๆ ผ่อนดัมเบลลงช้าๆ\r\nห้ามยักไหล่หรือใช้แรงจากบ่า (Trapezius) ในการช่วยยก และห้ามเหวี่ยงตัว',1,2,'uploads/weight_exercises/image/LateralRaise.jpg',NULL,3,'uploads/weight_exercises/videoloop/LateralRaise_loop.mp4',2),(17,'Front Raise','ท่ายกน้ำหนักขึ้นด้านหน้าตรง เพื่อเน้นสร้างความหนาและมัดกล้ามเนื้อให้หัวไหล่ส่วนหน้า','ยืนตรงถือดัมเบลวางไว้หน้าต้นขา หันฝ่ามือเข้าหาลำตัว แยกเท้าเท่าช่วงไหล่\r\nออกแรงยกดัมเบลขึ้นมาข้างหน้าตรงๆ จนแขนขนานกับพื้น ระดับเดียวกับสายตา แล้วค่อยๆ ผ่อนลง\r\nห้ามโยกตัวไปข้างหลังเพื่อส่งแรงเหวี่ยงน้ำหนักขึ้น',1,2,'uploads/weight_exercises/image/FrontRaise.jpg',NULL,3,'uploads/weight_exercises/videoloop/FrontRaise_loop.mp4',1),(18,'Rear Delt Fly','ท่ากางแขนยกดัมเบลในท่าย่อพับลำตัว เพื่อเจาะจงเน้นบริหารกล้ามเนื้อหัวไหล่ด้านหลังที่มักจะถูกมองข้าม','ยืนพับสะโพกลงมาให้ลำตัวเกือบขนานกับพื้น หลังตรง ถือดัมเบลห้อยลงในแนวดิ่ง งอศอกเล็กน้อย\r\nออกแรงกางแขนยกดัมเบลขึ้นด้านข้างตามแนวข้อศอก เพื่อเน้นไหล่หลัง แล้วผ่อนกลับช้าๆ\r\nอย่าบีบสะบักเข้าหากันมากเกินไป เพราะแรงจะย้ายจากไหล่หลังไปกล้ามเนื้อหลังส่วนบนแทน',1,2,'uploads/weight_exercises/image/RearDeltFly.jpg',NULL,3,'uploads/weight_exercises/videoloop/RearDeltFly_loop.mp4',1),(19,'Upright Row','ท่าดึงบาร์เบลหรือดัมเบลขึ้นตรงในแนวดิ่ง เน้นสร้างกล้ามเนื้อไหล่ด้านข้างและกล้ามเนื้อบ่าส่วนบน','ยืนตรงจับบาร์เบลหรือดัมเบลแบบคว่ำมือ ระยะห่างของมือแคบกว่าหัวไหล่เล็กน้อย ปล่อยแขนตรงข้างหน้า\r\nออกแรงดึงบาร์ขึ้นมาตรงๆ ในแนวดิ่งให้บาร์ชิดลำตัวที่สุด โดยยกข้อศอกให้สูงกว่าระดับมือเสมอ ดึงถึงระดับอก\r\nระวังอย่าฝืนดึงสูงเกินไปจนเจ็บข้อมือและข้อต่อหัวไหล่ (Impingement)',2,1,'uploads/weight_exercises/image/UprightRow.jpg',NULL,3,'uploads/weight_exercises/videoloop/UprightRow_loop.mp4',1),(20,'Dumbbell Curl','ยืนตัวให้มั่นคง','ยืนตรงแยกเท้าเท่าไหล่ ถือดัมเบลสองข้าง ฝ่ามือหันออกข้าง ปล่อยแขนตึงหนีบศอกชิดลำตัว\r\nออกแรงเกร็งหน้าแขนพับข้อศอกยกดัมเบลขึ้นมาจนสุดจังหวะ โดยที่ข้อศอกไม่ขยับเคลื่อนที่ แล้วผ่อนลงช้าๆ\r\nห้ามเหวี่ยงลำตัวและห้ามโยกศอกไปข้างหน้าเพื่อช่วยยกน้ำหนัก',1,1,'uploads/weight_exercises/image/DumbbellCurl.jpg','uploads/weight_exercises/video/DumbbellCurl.mp4',4,'uploads/weight_exercises/videoloop/DumbbellCurl_loop.mp4',1),(21,'Hammer Curl','ท่ายกดัมเบลในแนวตั้งคล้ายการจามขวาน เน้นสร้างความหนาของหน้าแขนด้านข้างและกล้ามเนื้อแขนท่อนล่าง','ยืนตรงถือดัมเบลสองข้างลำตัว หันฝ่ามือเข้าหาตนเอง (ขนานกัน) หนีบข้อศอกแน่นข้างลำตัว\r\nออกแรงพับข้อศอกยกดัมเบลขึ้นมาตรงๆ ในแนวตั้ง (ฝ่ามือยังหันเข้าหากันเหมือนเดิม) แล้วผ่อนลงช้าๆ\r\nคุมศอกให้อยู่นิ่งที่สุด ห้ามใช้แรงเหวี่ยงจากหัวไหล่',1,2,'uploads/weight_exercises/image/HammerCurl.jpg',NULL,4,'uploads/weight_exercises/videoloop/HammerCurl_loop.mp4',1),(22,'Preacher Curl','ท่าวางแขนบนเบาะลาดแล้วยกน้ำหนัก ช่วยล็อกข้อศอกไม่ให้ขยับเพื่อแยกโฟกัสกล้ามเนื้อหน้าแขนได้อย่างโดดเดี่ยว','นั่งบนม้านั่ง Preacher สอดแขนวางราบกับเบาะลาด ล็อกรักแร้ให้ชิดขอบเบาะ จับบาร์หรือดัมเบลหงายมือ\r\nออกแรงยกน้ำหนักขึ้นมาหาใบหน้าจนสุด โดยให้ต้นแขนแนบสนิทกับเบาะตลอดเวลา แล้วค่อยๆ ผ่อนลงจนสุดแขน\r\nตอนปล่อยน้ำหนักลงสุด ห้ามปล่อยกระชากเด็ดขาดเพราะอาจทำให้เอ็นข้อศอกฉีกขาดได้',2,3,'uploads/weight_exercises/image/PreacherCurl.jpg',NULL,4,'uploads/weight_exercises/videoloop/PreacherCurl_loop.mp4',2),(23,'Triceps Pushdown','ท่ากดสายเคเบิลลงด้านล่าง ท่ามาตรฐานยอดนิยมเพื่อสร้างความแข็งแรงและขนาดของกล้ามเนื้อหลังแขนทั้งหมด','ยืนหันหน้าเข้าหาเคเบิล ปรับรอกไว้ด้านบน จับบาร์สั้นหนีบข้อศอกชิดลำตัว โน้มตัวไปข้างหน้าเล็กน้อย\r\nออกแรงกดบาร์ลงด้านล่างจนแขนเหยียดตึงเป๊ะ เกร็งหลังแขน ค้างไว้เล็กน้อย แล้วผ่อนกลับขึ้นมาขนานพื้น\r\nห้ามกางข้อศอกออกด้านข้าง และอย่าปล่อยให้ไหล่ขยับขึ้นลงตามจังหวะน้ำหนัก',1,4,'uploads/weight_exercises/image/TricepsPushdown.jpg',NULL,5,'uploads/weight_exercises/videoloop/TricepsPushdown_loop.mp4',2),(24,'Skull Crusher','ท่านอนหงายหย่อนบาร์ลงหาหน้าผากแล้วเหยียดขึ้น เน้นโฟกัสกล้ามเนื้อหลังแขนส่วนยาวให้มีขนาดใหญ่หนา','นอนหงายบนม้านั่งราบ ถือสะพานบาร์ (EZ-Bar) ขึ้นตรงเหนืออก แขนตึง ตั้งแนวศอกทำมุมเอียงไปทางหัวเล็กน้อย\r\nงอข้อศอกหย่อนบาร์ลงมาช้าๆ มาที่บริเวณหน้าผากหรือเหนือศีรษะ โดยล็อกต้นแขนให้อยู่กับที่ จากนั้นเหยียดแขนขึ้น\r\nล็อกศอกให้ขนานกัน ห้ามศอกกางออกเด็ดขาด และห้ามปล่อยบาร์ตกใส่หน้า',2,1,'uploads/weight_exercises/image/SkullCrusher.jpg',NULL,5,'uploads/weight_exercises/videoloop/SkullCrusher_loop.mp4',2),(25,'Dips','ท่าดันตัวขึ้นลงบนบาร์คู่หรือม้านั่ง เพื่อบริหารกล้ามเนื้อหลังแขนและอกส่วนล่างด้วยการใช้น้ำหนักตัว','ขึ้นพยุงตัวบนบาร์คู่ แขนเหยียดตึง ล็อกหัวไหล่ลงให้แน่น งอเข่าไปด้านหลังเล็กน้อย\r\nผ่อนตัวลงช้าๆ โดยงอข้อศอกไปด้านหลังจนแขนท่อนบนขนานกับพื้น จากนั้นออกแรงดันตัวขึ้นสู่ท่าเริ่ม\r\nอย่าลงลึกเกินไปจนหัวไหล่เจ็บ และห้ามกางศอกออกด้านข้างกว้างเกิน 45 องศา',2,5,'uploads/weight_exercises/image/TricepsDips.jpg',NULL,5,'uploads/weight_exercises/videoloop/Dips_loop.mp4',1),(26,'Back Squat','ราชาแห่งท่าฝึกท่อนล่างที่สร้างกล้ามเนื้อหน้าขา ต้นขาด้านหลัง และก้นรวมทั้งหมด','วางบาร์เบลไว้บนกล้ามเนื้อบ่า (Trapezius) ยืนเท้ากว้างกว่าไหล่เล็กน้อย ปลายเท้าชี้ออกประมาณ 15-30 องศา\r\nสูดหายใจเข้า เกร็งท้อง ผลักสะโพกไปข้างหลังพร้อมย่อเข่าลงเหมือนนั่งเก้าอี้จนต้นขากลบขนานพื้น แล้วถีบตัวขึ้น\r\nห้ามหลังค่อม ห้ามส้นเท้ายก และระวังเข่าบิดเข้าหากัน (Knee Valgus) ตอนดันตัวขึ้น',3,1,'uploads/weight_exercises/image/BackSquat.jpg',NULL,7,'uploads/weight_exercises/videoloop/BackSquat_loop.mp4',1),(27,'Leg Press','ท่าถีบแผ่นน้ำหนักด้วยเครื่อง ช่วยเซฟหลังส่วนล่างและเน้นโฟกัสกล้ามเนื้อต้นขาโดยรวมได้อย่างหนักหน่วงและปลอดภัย','นั่งบนเครื่อง วางเท้าบนแผ่นเหล็กกว้างเท่าไหล่ ปรับเบาะให้หลังส่วนล่างและก้นแนบสนิทกับพนักพิง ปลดล็อกเซฟ\r\nผ่อนน้ำหนักลดแผ่นเหล็กลงมาช้าๆ จนเข่างอทำมุมประมาณ 90 องศา จากนั้นออกแรงถีบแผ่นเหล็กขึ้นตรงๆ\r\nห้ามถีบขาจนเข่าล็อกตึงเป๊ะเด็ดขาด และห้ามให้ก้นลอยขึ้นจากเบาะนั่ง',2,3,'uploads/weight_exercises/image/LegPress.jpg',NULL,7,'uploads/weight_exercises/videoloop/LegPress_loop.mp4',1),(28,'Romanian Deadlift (RDL)','ท่าพับสะโพกหย่อนบาร์เบลลงเพื่อยืดขา เน้นเจาะจงสร้างกล้ามเนื้อต้นขาด้านหลังและกล้ามเนื้อก้น','ยืนตรงถือบาร์เบลจับแบบคว่ำมือ กว้างเท่าไหล่ แยกเท้าเท่าสะโพก ยืดอก หลังตรง งอเข่าเล็กน้อยแค่องศาเดียวคงที่\r\nพับสะโพกไปข้างหลัง (Hinge) พร้อมหย่อนบาร์เบลลงมาตามผิวหน้าขาจนรู้สึกตึงที่ต้นขาด้านหลัง แล้วดันสะโพกกลับมายืนตรง\r\nห้ามงอเข่าเพิ่ม (เพราะจะกลายเป็น Squat) และห้ามหลังงอขณะก้มตัว',2,1,'uploads/weight_exercises/image/RomanianDeadlift.jpg',NULL,8,'uploads/weight_exercises/videoloop/RomanianDeadlift_loop.mp4',1),(29,'Bulgarian Split Squat','ท่าย่อตัวขาทีละข้างโดยพาดขาหลังไว้บนม้านั่ง เน้นแก้อาการแรงขาไม่เท่ากันและสร้างความแข็งแรงให้หน้าขาและก้น','ยืนหันหลังให้ม้านั่ง พาดหลังเท้าข้างหนึ่งไว้บนม้านั่ง ก้าวขาอีกข้างไปข้างหน้าในระยะที่เหมาะสม ลำตัวตรง\r\nย่อตัวลงตรงๆ จนเข่าด้านหลังเกือบแตะพื้น (เข่าหน้าทำมุม 90 องศา) ออกแรงถีบเท้าหน้าดันตัวกลับขึ้นมา\r\nระวังเข่าหน้ายื่นเลยปลายเท้าเกินไปจนเจ็บ และระวังการสูญเสียการทรงตัว ควรมองตรงไปข้างหน้า',3,2,'uploads/weight_exercises/image/BulgarianSplitSquat.jpg',NULL,7,'uploads/weight_exercises/videoloop/BulgarianSplitSquat_loop.mp4',1),(30,'Leg Extension','ท่าเหยียดเตะขาบนเครื่องพินโหลด เพื่อเจาะจงแยกโฟกัสกล้ามเนื้อหน้าขาให้ตัดเป็นมัดคมชัด','นั่งบนเครื่องปรับพนักพิงให้ข้อพับเข่าชิดขอบเบาะ สอดเท้าไว้ใต้เบาะนวมทรงกระบอก มือจับราวด้านข้างให้แน่น\r\nออกแรงเกร็งหน้าขาเหยียดขาเตะขึ้นมาตรงๆ จนสุด ค้างไว้ 1 วินาที แล้วค่อยๆ ผ่อนขากลับลงช้าๆ\r\nอย่าสะบัดกระชากเท้าขึ้นรุนแรง และห้ามปล่อยให้น้ำหนักตกกระแทก',1,3,'uploads/weight_exercises/image/LegExtension.jpg',NULL,7,'uploads/weight_exercises/videoloop/LegExtension_loop.mp4',2),(31,'Lying Leg Curl','ท่านอนคว่ำพับงอขาบนเครื่อง เพื่อแยกโฟกัสสร้างความแข็งแรงและมวลกล้ามเนื้อต้นขาด้านหลังโดยตรง','นอนคว่ำลงบนเครื่อง ปรับเบาะนวมทรงกระบอกให้อยู่บริเวณข้อเท้าด้านหลัง จับด้ามจับด้านหน้า ล็อกสะโพกติดเบาะ\r\nออกแรงเกร็งต้นขาด้านหลัง พับงอขาขึ้นมาจนเบาะนวมเกือบแตะก้น เกร็งค้างไว้ แล้วผ่อนกลับลงช้าๆ\r\nห้ามยกสะโพกลอยขึ้นจากเบาะขณะออกแรงพับขา',1,3,'uploads/weight_exercises/image/LyingLegCurl.jpg',NULL,8,'uploads/weight_exercises/videoloop/LyingLegCurl_loop.mp4',2),(32,'Hip Thrust','ท่าพาดบาร์เบลบนสะโพกแล้วดันตัวขึ้น ท่าที่ดีที่สุดในการเจาะจงสร้างกล้ามเนื้อก้นให้กลมโตและทรงพลัง','นั่งพิงหลังส่วนบน (สะบัก) กับม้านั่งราบ วางบาร์เบลไว้บนแผ่นนวมตรงกระดูกเชิงกราน วางเท้าติดพื้นเข่างอ\r\nออกแรงดันสะโพกขึ้นในแนวดิ่งจนลำตัวขนานกับพื้น (เข่าทำมุม 90 องศา) บีบก้นให้แน่น แล้วผ่อนสะโพกลงช้าๆ\r\nห้ามแอ่นหลังส่วนล่างช่วยยก ให้ใช้แรงขับเคลื่อนหลักจากกล้ามเนื้อก้นเท่านั้น',2,1,'uploads/weight_exercises/image/HipThrust.jpg','https://youtube.com/shorts/CvuVYMFd11g',8,'uploads/weight_exercises/videoloop/HipThrust_loop.mp4',1),(33,'Calf Raise','ท่ายกส้นเท้าเขย่งขึ้นในท่ายืน เพื่อบริหารและเพิ่มความหนาแน่นให้กับกล้ามเนื้อน่องส่วนนอก','ยืนบนแท่นเหยียบ ยืนด้วยปลายเท้าเท้ากว้างเท่าสะโพก ปล่อยส้นเท้าหย่อนลงมาให้น่องยืดสุด มือจับที่ประคอง\r\nออกแรงเกร็งกล้ามเนื้อน่อง ดันปลายเท้าเขย่งตัวขึ้นให้สูงที่สุด ค้างไว้ 1 วินาที แล้วผ่อนส้นเท้าลงช้าๆ จนสุด\r\nห้ามงอหัวเข่าช่วยเด้งตัว (ให้ล็อกเข่าตรงตึงไว้) และระวังการทิ้งส้นเท้าลงมาเร็วเกินไป',1,3,'uploads/weight_exercises/image/StandingCalfRaise.jpg',NULL,7,'uploads/weight_exercises/videoloop/CalfRaise_loop.mp4',2),(34,'Plank','ท่าชันศอกเกร็งตัวตรงขนานกับพื้น ท่าพื้นฐานเพื่อฝึกความทนทานและความแข็งแรงของกล้ามเนื้อแกนกลางลำตัวทั้งหมด','นอนคว่ำ ตั้งศอกลงบนพื้นกว้างเท่าไหล่ (ศอกตรงกับหัวไหล่) ตั้งปลายเท้าสองข้างขึ้น ขึงลำตัวตรง\r\nเกร็งหน้าท้อง ขลิบก้น และเกร็งต้นขาพยุงตัวให้ขนานกับพื้นคล้ายแผ่นกระดาน หายใจเข้าออกสม่ำเสมอตามเวลา\r\nห้ามปล่อยให้สะโพกตกหรือยกก้นโด่งสูงเกินไป รักษาแนวคอให้ตรงไม่ก้มหน้า',1,5,'uploads/weight_exercises/image/Plank.jpg',NULL,9,'uploads/weight_exercises/videoloop/Plank_loop.mp4',1),(35,'Hanging Leg Raise','ท่าโหนบาร์ยกขาขึ้นด้านบน เน้นเจาะจงสร้างความแข็งแรงและความคมชัดของกล้ามเนื้อหน้าท้องส่วนล่าง','โน้มตัวกระโดดจับบาร์เดี่ยว ปล่อยตัวห้อยตรง เกร็งแกนกลางลำตัวเพื่อไม่ให้ตัวแกว่งไปมา\r\nออกแรงเกร็งหน้าท้องล่าง ม้วนสะโพกยกขาขึ้นมาข้างหน้าจนขาขนานกับพื้น (หรือชันเข่าขึ้นมาหาอก) แล้วผ่อนลงช้าๆ\r\nห้ามใช้แรงเหวี่ยงจากสะโพกหรือขาโหนตัวไปมา ให้ใช้แรงจากหน้าท้องควบคุมการเคลื่อนไหว',2,5,'uploads/weight_exercises/image/HangingLegRaise.jpg',NULL,9,'uploads/weight_exercises/videoloop/HangingLegRaise_loop.mp4',1),(36,'Russian Twist','ท่านั่งบิดลำตัวซ้ายขวาพร้อมยกขาขึ้นเล็กน้อย เพื่อเน้นสร้างความแข็งแรงของกล้ามเนื้อหน้าท้องด้านข้าง','นั่งบนพื้น เอนลำตัวไปข้างหลังเล็กน้อย (ทำมุม 45 องศา) งอเข่ายกเท้าลอยเหนือพื้นเล็กน้อย ประสานมือไว้ข้างหน้า\r\nออกแรงหมุนบิดเอวและลำตัวท่อนบนไปทางซ้ายจนสุด จากนั้นบิดสลับมาทางขวา โดยรักษาตำแหน่งขาทั้งสองข้างให้อยู่นิ่ง\r\nระวังอย่าบิดแค่แขน ให้บิดหมุนที่ช่วงเอวและแกนกลางลำตัวจริงๆ',1,2,'uploads/weight_exercises/image/RussianTwist.jpg',NULL,9,'uploads/weight_exercises/videoloop/RussianTwist_loop.mp4',2),(37,'Incline Dumbbell Curl','ท่านั่งบนม้านั่งเอียงลาดแล้วยกดัมเบล ช่วยยืดหัวกล้ามเนื้อหน้าแขนส่วนยาวให้ทำงานได้ลึกและยาวขึ้น','นั่งบนม้านั่งเอียงลาด 45 องศา ปล่อยแขนสองข้างห้อยลงตรงๆ ในแนวดิ่ง หันฝ่ามืออกไปข้างหน้า\r\nออกแรงเกร็งหน้าแขนยกดัมเบลขึ้นมาทีละข้างหรือพร้อมกัน ล็อกข้อศอกให้อยู่กับที่ในแนวดิ่ง แล้วผ่อนลงช้าๆ\r\nระวังอย่าให้ข้อศอกขยับเดินหน้าตามดัมเบลขณะที่กำลังยกขึ้น',2,2,'uploads/weight_exercises/image/InclineDumbbellCurl.jpg',NULL,4,'uploads/weight_exercises/videoloop/InclineDumbbellCurl_loop.mp4',2),(38,'Rope Pushdown','ท่ากดเชือกเคเบิลลงด้านล่างพร้อมกางเชือกออกตอนสุดทาง ช่วยบีบโฟกัสกล้ามเนื้อหลังแขนด้านนอกให้คมชัด','ยืนหันหน้าเข้าหาเคเบิล จับปลายเชือกสองข้าง หนีบศอกชิดตัว โน้มตัวไปข้างหน้าเล็กน้อย เข่างอเล็กน้อย\r\nกดเชือกลงด้านล่าง เมื่อแขนเกือบตึงให้แบะมือแยกปลายเชือกออกจากกัน เพื่อบีบหลังแขนส่วนนอก แล้วผ่อนกลับ\r\nล็อกต้นแขนและข้อศอกให้อยู่นิ่งข้างลำตัวตลอดเวลา ห้ามขยับตามเชือก',1,4,'uploads/weight_exercises/image/RopePushdown.jpg',NULL,5,'uploads/weight_exercises/videoloop/RopePushdown_loop.mp4',2),(39,'Straight Arm Pulldown','ท่าดึงเคเบิลแขนตึงลงมาหาต้นขา เพื่อแยกโฟกัสกล้ามเนื้อปีกหลังโดยตรงโดยไม่ใช้แรงแขนหน้าเข้าช่วย','ยืนหันหน้าเข้าหาเคเบิล ปรับรอกไว้ด้านบน จับบาร์ตรงถอยหลังมาเล็กน้อย พับสะโพกไปข้างหลัง แขนเหยียดตรงตึง\r\nออกแรงกดบาร์ลงมาเป็นเส้นโค้งจนบาร์แตะหน้าขา โดยไม่งอข้อศอก เกร็งปีกหลัง แล้วผ่อนกลับช้าๆ\r\nห้ามใช้แรงจากแขนหลัง (Triceps) ในการกดน้ำหนัก ให้ล็อกข้อศอกคงที่ไว้ตลอดเวลา',1,4,'uploads/weight_exercises/image/StraightArmPulldown.jpg',NULL,2,'uploads/weight_exercises/videoloop/StraightArmPulldown_loop.mp4',1),(40,'Reverse Fly','ท่ากางแขนไปด้านหลังด้วยเครื่องหรือเคเบิล เพื่อเจาะจงแยกโฟกัสกล้ามเนื้อหัวไหล่ด้านหลังและหลังท่อนบนอย่างแม่นยำ','นั่งหันหน้าเข้าหาเครื่อง Pec Deck Fly ปรับเบาะให้ด้ามจับอยู่ระดับไหล่ จับด้ามจับยืดอกขึ้น หลังตรง\r\nออกแรงกางแขนผลักด้ามจับไปทางด้านหลังจนแขนกางเป็นแนวเส้นตรง เกร็งไหล่หลัง แล้วผ่อนกลับช้าๆ\r\nรักษาแนวศอกให้อยู่ในระดับเดียวกับหัวไหล่ตลอดการเคลื่อนไหว ไม่ให้ศอกตก',1,3,'uploads/weight_exercises/image/ReverseFly.jpg',NULL,3,'uploads/weight_exercises/videoloop/ReverseFly_loop.mp4',1),(41,'Farmers Walk','ท่าถือดัมเบลหนักสองข้างแล้วเดินไปข้างหน้า ช่วยสร้างแรงบีบมือ ความแข็งแรงของแกนกลางลำตัว และกล้ามเนื้อบ่ารวมกัน','ยืนตรงระหว่างดัมเบลหรือเคตเติ้ลเบลหนัก ย่อตัวยกน้ำหนักขึ้นมาถือไว้ข้างลำตัว ยืดอก หลังตรง ไหล่ไม่ห่อ\r\nเกร็งแกนกลางลำตัวและข้อศอกให้แน่น ก้าวเดินไปข้างหน้าด้วยก้าวที่สั้นและมั่นคง รักษาแนวกระดูกสันหลังให้ตรง\r\nห้ามเดินหลังค่อมหรือเดินเซ และระวังอย่าปล่อยให้น้ำหนักแกว่งไปมากระแทกต้นขา',2,2,'uploads/weight_exercises/image/FarmersWalk.jpg',NULL,9,'uploads/weight_exercises/videoloop/FarmersWalk_loop.mp4',1),(42,'Seated Dumbbell Press','ท่านั่งดันดัมเบลขึ้นเหนือศีรษะ ช่วยตัดแรงส่งจากท่อนล่างเพื่อโฟกัสสร้างมวลกล้ามเนื้อหัวไหล่โดยรวมอย่างเต็มที่','นั่งบนม้านั่งปรับเบาะตั้งชัน 90 องศา ถือดัมเบลตั้งขึ้นข้างใบหู ศอกทำมุม 90 องศา ฝ่ามือหันออก\r\nออกแรงดันดัมเบลขึ้นเหนือศีรษะให้ดัมเบลเข้าหากันเล็กน้อยตอนสุดทาง แล้วค่อยๆ ผ่อนลงช้าๆ มาที่ระดับหู\r\nอย่าปล่อยให้ข้อศอกกางไปทางด้านหลังมากเกินไป ให้งอเข้าหาด้านหน้าเล็กน้อยเพื่อความปลอดภัยของไหล่',2,2,'uploads/weight_exercises/image/SeatedDumbbellPress.jpg',NULL,3,'uploads/weight_exercises/videoloop/SeatedDumbbellPress_loop.mp4',1),(43,'Overhead Tricep Extension','ท่ายกน้ำหนักหรือสายเคเบิลเหยียดขึ้นเหนือศีรษะ เพื่อยืดและสร้างกล้ามเนื้อหลังแขนส่วนยาวให้เต็มอิ่ม','นั่งหรือยืน ถือดัมเบลหรือเชือกเคเบิลยกขึ้นเหนือศีรษะ ชูแขนตรง หนีบข้อศอกเข้าหาใบหู\r\nงอศอกหย่อนดัมเบลลงไปทางด้านหลังศีรษะช้าๆ จนหลังแขนรู้สึกตึง จากนั้นออกแรงเหยียดแขนดันกลับขึ้นไปตรงๆ\r\nอย่ากางศอกออกกว้าง และรักษาแกนกลางลำตัวให้ตรง ห้ามแอ่นหลังพ่นพุง',2,2,'uploads/weight_exercises/image/OverheadTricepExtension.jpg',NULL,5,'uploads/weight_exercises/videoloop/OverheadTricepExtension_loop.mp4',2),(44,'Dumbbell Bench Press','ท่าดันดัมเบลนอนราบ ช่วยเพิ่มช่วงการเคลื่อนไหวให้ลึกขึ้นเพื่อบีบโฟกัสกล้ามเนื้ออกซ้ายขวาได้อย่างอิสระ','นอนหงายบนม้านั่งราบ ถือดัมเบลระดับอก หันฝ่ามือไปทางปลายเท้า วางเท้าติดพื้นให้มั่นคง\r\nออกแรงดันดัมเบลขึ้นตรงๆ พร้อมกันจนแขนตึง ตอนลงให้ผ่อนลงช้าๆ จนดัมเบลอยู่ข้างอก\r\nระวังดัมเบลส่ายขยับไม่เท่ากัน ควบคุมจังหวะให้บาลานซ์ซ้ายขวา',2,2,'uploads/weight_exercises/image/DumbbellBenchPress.jpg',NULL,1,'uploads/weight_exercises/videoloop/DumbbellBenchPress_loop.mp4',1),(45,'Crunch','ท่านอนราบยกสะบักขึ้นจากพื้นเล็กน้อย เพื่อเจาะจงกระตุ้นและสร้างมัดซิกแพคบริเวณหน้าท้องส่วนบน','นอนหงายบนพื้น ชันเข่าสองข้างขึ้น เท้าลอยหรือวางราบ นำมือมาแตะไว้ข้างขมับหรือไขว้ไว้ที่หน้าอก\r\nหายใจออกพร้อมเกร็งหน้าท้องส่วนบน ม้วนกระดูกโครงอกยกสะบักไหล่ลอยขึ้นจากพื้นเล็กน้อย ค้างไว้แล้วผ่อนลง\r\nห้ามใช้มือประสานหลังคอแล้วกระชากศีรษะขึ้นมาเด็ดขาด เพราะจะทำให้เจ็บกล้ามเนื้อคอ',1,5,'uploads/weight_exercises/image/Crunch.jpg',NULL,9,'uploads/weight_exercises/videoloop/Crunch_loop.mp4',2),(46,'Hack Squat','ท่าย่อตัวสควอทบนเครื่องสไลด์เฉียง ช่วยลดภาระที่หลังส่วนล่างเพื่อระเบิดพลังใส่กล้ามเนื้อหน้าขาได้อย่างเต็มพิกัด','เข้าไปยืนบนเครื่องเอาไหล่หนุนนวม วางเท้าบนแผ่นเหล็กกว้างเท่าไหล่ หลังและสะโพกแนบสนิทกับพนักพิง ปลดล็อกเซฟ\r\nย่อตัวลงช้าๆ จนเข่างอทำมุมขนานขอบแผ่นเหล็ก จากนั้นออกแรงถีบเท้าดันตัวกลับขึ้นมาท่าเริ่ม\r\nห้ามให้ส้นเท้ายกขึ้นจากแผ่นวางเท้า และห้ามล็อกเข่าตึงตอนยืนสุด',2,3,'uploads/weight_exercises/image/HackSquat.jpg',NULL,7,'uploads/weight_exercises/videoloop/HackSquat_loop.mp4',1),(47,'Seated Calf Raise','ท่านั่งเขย่งส้นเท้าบนเครื่อง เพื่อเจาะจงบริหารกล้ามเนื้อน่องส่วนลึกด้านใน','นั่งบนเครื่องวางปลายเท้าบนแท่น วางเบาะนวมล็อกไว้บนต้นขาเหนือเข่าเล็กน้อย ปลดตัวล็อกออก\r\nหย่อนส้นเท้าลงให้สุดเพื่อยืดน่อง จากนั้นเกร็งน่องดันปลายเท้าเขย่งขึ้นให้สูงที่สุดเท่าที่จะทำได้ แล้วผ่อนลงช้าๆ\r\nควบคุมจังหวะช้าๆ ห้ามใช้จังหวะเด้งกระแทก (Bounce) น้ำหนักขึ้นลง',1,3,'uploads/weight_exercises/image/SeatedCalfRaise.jpg',NULL,7,'uploads/weight_exercises/videoloop/SeatedCalfRaise_loop.mp4',2),(50,'T-Bar Row','ท่าดึงบาร์รูปตัว T เข้าหาลำตัวด้วยเครื่องช่วยพยุงอก เน้นสร้างความหนาและความแข็งแรงของกล้ามเนื้อหลังส่วนกลางและส่วนบน โดยลดแรงกดที่หลังส่วนล่างเมื่อเทียบกับท่าก้มตัวดึงบาร์เบลปกติ','ปรับความสูงเบาะให้พอดี นั่งพิงอกกับเบาะรองและวางเท้าราบกับแท่นวางเท้า\r\nจับด้ามจับแบบคว่ำมือ กว้างกว่าหัวไหล่เล็กน้อย รักษาหลังให้ตรงและเกร็งแกนกลางลำตัว\r\nออกแรงดึงด้ามจับเข้าหาลำตัว บีบสะบักเข้าหากันที่จุดสูงสุด ค้างไว้ครู่หนึ่ง\r\nผ่อนแขนกลับสู่ท่าเริ่มต้นช้าๆ ทำซ้ำตามจำนวนครั้งที่ต้องการ',2,3,'uploads/weight_exercises/image/T-BarRow.jpg','uploads/weight_exercises/video/T-BarRow.mp4',2,'uploads/weight_exercises/videoloop/TBarRow_loop.mp4',1),(65,'เบนช์เพรส (Test)','นอนหงายบนม้านั่ง จับบาร์เบลกว้างกว่าหัวไหล่เล็กน้อย ดันบาร์ขึ้นจนแขนเหยียดตรง แล้วลดลงจนบาร์แตะหน้าอก','หายใจเข้าขณะลดบาร์ลง หายใจออกขณะดันบาร์ขึ้น 2* เกร็งสะบักและแผ่นหลังตลอดการฝึก',2,1,'uploads/weight_exercises/image/1788159562764498600.png','https://youtube.com/shorts/IqvIZ89KYc4?si=EqHEI5K7xWs-8hvX',NULL,'uploads/weight_exercises/videoloop/1788159562768323700_loop.mp4',1);
