INSERT INTO `cardio_category` VALUES (1,'เครื่องยิม','ความเข้มข้นต่ำต่อเนื่อง รักษาอัตราการเต้นหัวใจคงที่ เน้นเบิร์นไขมัน ไม่กินกล้ามเนื้อ','uploads/cardio_categories/1788151203025116500.jpg'),(3,'กีฬาและกิจกรรม','ความเข้มข้นปานกลาง เพิ่มความอึดของปอดและหัวใจ','uploads/cardio_categories/1788151196610994000.jpg'),(23,'วิ่ง (Running)','วิ่งด้วยความเร็วปานกลางอย่างต่อเนื่อง เหมาะสำหรับการเผาผลาญไขมันและเสริมสร้างความแข็งแรงของหัวใจ','uploads/cardio_categories/1788159932734956500.jpg');
/*!40000 ALTER TABLE `cardio_category` ENABLE KEYS */;
