LOCK TABLES `workout_plan_template` WRITE;
/*!40000 ALTER TABLE `workout_plan_template` DISABLE KEYS */;
INSERT INTO `workout_plan_template` VALUES (1,'Full Body','เหมาะกับใคร : มือใหม่ หรือคนงานยุ่ง\nจุดเด่น : บริหารครบทุกส่วนในวันเดียว สลับ Full Body A / B เพื่อให้กล้ามเนื้อได้รับการกระตุ้นสม่ำเสมอ',3,2,'uploads/weight_exercises/plan/fullbody_saver.jpg'),(2,'Upper / Lower','เหมาะกับใคร : คนที่ออกกำลังกายมาสักพัก\nจุดเด่น : แยกส่วนบน/ส่วนล่าง ให้กล้ามเนื้อแต่ละส่วนพัก 72 ชั่วโมง',4,2,'uploads/weight_exercises/plan/upper_lower.jpg'),(3,'Body Split','เหมาะกับใคร : สายฟิตเนสที่ต้องการเพิ่ม Volume\nจุดเด่น : ครึ่งสัปดาห์แรกแบบ Upper/Lower ครึ่งหลังเป็น Push/Pull/Legs',5,2,'uploads/weight_exercises/plan/hybrid_power.jpg'),(4,'Push / Pull / Legs','เหมาะกับใคร : นักกีฬาหรือคนที่ฝึกมาอย่างจริงจัง\nจุดเด่น : แบ่งกลุ่มกล้ามเนื้อตามการเคลื่อนไหว Push/Pull/Legs วนซ้ำ 2 รอบ/สัปดาห์',6,3,'uploads/weight_exercises/plan/hardcore_ppl.jpg'),(18,'แผนฝึกเริ่มต้น Full Body 3 วัน','แผนฝึกสำหรับผู้เริ่มต้นออกกำลังกาย เน้นฝึกกล้ามเนื้อทุกส่วนของร่างกายในแต่ละครั้ง เหมาะสำหรับผู้ที่มีเวลาฝึกจำกัด',3,1,'uploads/workout_plans/1788160438392269000.jpg');
/*!40000 ALTER TABLE `workout_plan_template` ENABLE KEYS */;
UNLOCK TABLES;

